import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Triggers and When They Execute","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/triggers-and-when-they-execute.md","filePath":"your-first-al-programs/triggers-and-when-they-execute.md"}`),a={name:`your-first-al-programs/triggers-and-when-they-execute.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="triggers-and-when-they-execute" tabindex="-1">Triggers and When They Execute <a class="header-anchor" href="#triggers-and-when-they-execute" aria-label="Permalink to “Triggers and When They Execute”">​</a></h1><p>In AL, <strong>triggers are special code blocks that execute automatically when a particular event occurs</strong>. They allow us to respond to actions such as opening a page, inserting a record, or modifying a field.</p><h2 id="page-triggers" tabindex="-1">Page Triggers <a class="header-anchor" href="#page-triggers" aria-label="Permalink to “Page Triggers”">​</a></h2><p>Page triggers execute in response to events involving a page.</p><table tabindex="0"><thead><tr><th>Trigger</th><th>When It Executes</th></tr></thead><tbody><tr><td><code>OnInit</code></td><td>When the page is initialized, before its normal initialization process completes.</td></tr><tr><td><code>OnOpenPage</code></td><td>When the page is opened.</td></tr><tr><td><code>OnAfterGetRecord</code></td><td>When a record is retrieved and made available to the page.</td></tr><tr><td><code>OnAfterGetCurrRecord</code></td><td>After the current record has been retrieved.</td></tr><tr><td><code>OnClosePage</code></td><td>When the page is closed.</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><p><strong>File:</strong> <code>CustomerList.PageExt.al</code></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;The Customer List page has opened.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>When a user opens the Customer List page, the <code>OnOpenPage</code> trigger executes and displays the message.</p><h2 id="table-triggers" tabindex="-1">Table Triggers <a class="header-anchor" href="#table-triggers" aria-label="Permalink to “Table Triggers”">​</a></h2><p>Table triggers execute in response to operations involving table records.</p><table tabindex="0"><thead><tr><th>Trigger</th><th>When It Executes</th></tr></thead><tbody><tr><td><code>OnInsert</code></td><td>When a record is inserted through the AL record insertion process.</td></tr><tr><td><code>OnModify</code></td><td>When an existing record is modified through the AL record modification process.</td></tr><tr><td><code>OnDelete</code></td><td>When a record is deleted through the AL record deletion process.</td></tr><tr><td><code>OnRename</code></td><td>When a record&#39;s primary key is changed through the AL record renaming process.</td></tr><tr><td><code>OnBeforeInsertEvent</code></td><td>When the corresponding table event is raised before a record is inserted.</td></tr><tr><td><code>OnAfterInsertEvent</code></td><td>When the corresponding table event is raised after a record is inserted.</td></tr></tbody></table><h3 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tableextension 50101 CustomerTableExt extends Customer</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnAfterInsert()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;A customer record has been inserted.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>Important:</strong> <code>OnAfterInsert()</code> is not a table trigger in AL. The table trigger is <code>OnInsert()</code>. To subscribe to the after-insert table event, use an event subscriber such as <code>[EventSubscriber(ObjectType::Table, Database::Customer, &#39;OnAfterInsertEvent&#39;, &#39;&#39;, false, false)]</code>.</p><p>For example, a table extension can use <code>OnInsert()</code> to execute logic as part of the insertion process.</p><h2 id="field-triggers" tabindex="-1">Field Triggers <a class="header-anchor" href="#field-triggers" aria-label="Permalink to “Field Triggers”">​</a></h2><p>Field triggers execute in response to changes to table fields.</p><table tabindex="0"><thead><tr><th>Trigger</th><th>When It Executes</th></tr></thead><tbody><tr><td><code>OnValidate</code></td><td>When a field is validated, allowing you to check or react to its value.</td></tr></tbody></table><h3 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tableextension 50102 CustomerTableExt extends Customer</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        modify(Name)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            trigger OnAfterValidate()</span></span>
<span class="line"><span>            begin</span></span>
<span class="line"><span>                Message(&#39;The customer name has been validated.&#39;);</span></span>
<span class="line"><span>            end;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>OnAfterValidate()</code> runs after the <code>Name</code> field&#39;s validation logic completes.</p><h2 id="codeunit-triggers" tabindex="-1">Codeunit Triggers <a class="header-anchor" href="#codeunit-triggers" aria-label="Permalink to “Codeunit Triggers”">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>When It Executes</th></tr></thead><tbody><tr><td><code>OnRun</code></td><td>When the codeunit is executed, for example, through <code>Codeunit.Run()</code>.</td></tr></tbody></table><h3 id="example-3" tabindex="-1">Example <a class="header-anchor" href="#example-3" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50103 GreetingCodeunit</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnRun()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;The codeunit is running.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The message appears when this codeunit is executed.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>Triggers let you execute code in response to specific events.</li><li>Different triggers belong to different AL objects.</li><li>The trigger&#39;s execution depends on the event or operation that activates it.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/page/devenv-page-triggers" target="_blank" rel="noreferrer">Page triggers — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/table/devenv-table-triggers" target="_blank" rel="noreferrer">Table triggers — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/field/devenv-field-triggers" target="_blank" rel="noreferrer">Field triggers — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/codeunit/devenv-codeunit-triggers" target="_blank" rel="noreferrer">Codeunit triggers — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-events-in-al" target="_blank" rel="noreferrer">Event subscribers — Microsoft Learn</a></li></ul>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};